if (typeof msg.payload !== "number" ||
    !Number.isFinite(msg.payload)) {
    node.warn("Invalid temperature");
    return null;
}

msg.topic = "Temperature Istwert";
return msg;

let temperature = msg.payload;

let setpoint = flow.get("setpoint");
let coolingState = flow.get("coolingState");

if (setpoint === undefined) {
    setpoint = 23;
}

if (coolingState === undefined) {
    coolingState = false;
}

let onThreshold = setpoint + 1;
let offThreshold = setpoint - 1;

if (temperature >= onThreshold) {
    coolingState = true;
}

if (temperature <= offThreshold) {
    coolingState = false;
}

flow.set("coolingState", coolingState);

msg.setpoint = setpoint;
msg.onThreshold = onThreshold;
msg.offThreshold = offThreshold;
msg.coolingDemand = coolingState;

return msg;

let autoMode = flow.get("autoMode");
let manualFanCommand = flow.get("manualFanCommand");
let fanFeedback = flow.get("fanFeedback");

if (autoMode === undefined) {
    autoMode = true;
}

if (manualFanCommand === undefined) {
    manualFanCommand = false;
}

if (fanFeedback === undefined) {
    fanFeedback = false;
}

// Existing operating-mode logic
const dataTimeout = msg.dataTimeout === true;

if (autoMode === true) {
    msg.operationMode = "AUTO";

    if (dataTimeout) {
        msg.fanCommand = false;
    } else {
        msg.fanCommand = msg.coolingDemand === true;
    }

} else {
    msg.operationMode = "MANUAL";
    msg.fanCommand = manualFanCommand === true;
}

msg.fanFeedback = fanFeedback;

// Fan feedback monitoring
const feedbackDelayMs = 5000;
const now = Date.now();

let feedbackMissingSince = context.get("feedbackMissingSince");

if (msg.fanCommand === true && fanFeedback === false) {

    // Start timing when missing feedback is first detected.
    if (feedbackMissingSince === undefined) {
        feedbackMissingSince = now;
        context.set("feedbackMissingSince", feedbackMissingSince);
    }

    const elapsedMs = now - feedbackMissingSince;

    msg.fanStartPending = elapsedMs < feedbackDelayMs;

    if (elapsedMs >= feedbackDelayMs) {
        msg.alarm = true;
        msg.alarmText = "Fan fault: Command ON but no feedback";

    } else {
        msg.alarm = false;
        msg.alarmText = "Waiting for fan feedback";
    }

} else {
    // Command OFF or feedback received: reset the monitoring.
    context.set("feedbackMissingSince", undefined);

    msg.fanStartPending = false;
    msg.alarm = false;
    msg.alarmText = "No alarm";
}

return msg;

msg.payload = {
    value: 246,
    register: "input",
    address: 0,
    disableMsgOutput: 0
};

return msg;

let setpoint = flow.get("setpoint");
if (setpoint === undefined || setpoint === 0) {
    flow.set("setpoint", 23);
}

if (!Array.isArray(msg.payload) || msg.payload.length === 0) {
    return null;
}

const rawValue = Number(msg.payload[0]);
if (!Number.isFinite(rawValue) || rawValue === 0) {
    return null;
}

msg.payload = rawValue * 0.1;
flow.set("setpoint", msg.payload);
msg.topic = "Setpoint";
return msg;

msg.payload = {
    value: msg.payload,
    register: "discrete",
    address: 0,
    disableMsgOutput: 0
};

return msg;

let feedback;

if (Array.isArray(msg.payload)) {
    feedback = msg.payload[0];
} else {
    feedback = msg.payload;
}

flow.set("fanFeedback", feedback);

return msg;

// Keep Modbus buffers and transport metadata out of chart history.
// The control branches retain their original complete messages.
return { payload: msg.payload, topic: msg.topic };

if (msg.alarm === true) {
    msg.payload = "ALARM - Fan fault";
} else {
    msg.payload = "No alarm";
}

return msg;

// Convert the fan command to an MQTT message
msg.payload = msg.fanCommand === true ? "ON" : "OFF";
msg.topic = "bms/room1/fan/command";

return msg;

const humidity = Number(msg.payload);

if (!Number.isFinite(humidity) ||
    humidity < 0 ||
    humidity > 100) {
    return null;
}

return {
    payload: humidity,
    topic: "Relative Luftfeuchtigkeit"
};

// Virtual cooling valve command
const coolingDemand = msg.coolingDemand === true;
const fanCommand = msg.fanCommand === true;
const fanFeedback = msg.fanFeedback === true;
const dataTimeout = msg.dataTimeout === true;

msg.valveCommand =
    !dataTimeout &&
    coolingDemand &&
    fanCommand &&
    fanFeedback;

msg.valveStatus = msg.valveCommand
    ? "OFFEN"
    : "GESCHLOSSEN";

return msg;

const now = Date.now();

// Keep the accumulated total on disk.
let totalMs = context.get("totalMs", "file") || 0;

// Keep timing and command state in memory only.
const lastUpdate = context.get("lastUpdate");
const previousCommand = context.get("previousCommand");

if (lastUpdate !== undefined && previousCommand === true) {
    const elapsed = now - lastUpdate;

    if (elapsed > 0 && elapsed <= 5000) {
        totalMs += elapsed;
    }
}

context.set("totalMs", totalMs, "file");
context.set("lastUpdate", now);
context.set("previousCommand", msg.fanCommand === true);

msg.fanCommandSeconds = Math.floor(totalMs / 1000);
msg.fanCommandHours = totalMs / 3600000;

return msg;

msg.payload = msg.valveCommand === true ? "ON" : "OFF";
msg.topic = "bms/room1/valve/command";

return msg;

// Process only messages containing an evaluated alarm state.
if (typeof msg.alarm !== "boolean") {
    return null;
}

// Restore the last three alarm records from disk.
let history = context.get("fanAlarmHistory", "file");

if (!Array.isArray(history)) {
    history = [];
}

const activeRecord = history.find(
    record => record.status === "AKTIV"
);

const timestamp = new Date().toLocaleString("de-DE", {
    timeZone: "Europe/Berlin"
});

let changed = false;

if (msg.alarm === true && !activeRecord) {
    // New alarm: create one record only.
    history.unshift({
        raisedAt: timestamp,
        clearedAt: "",
        status: "AKTIV",
        text: "Lüfter: Keine Rückmeldung bei Einschaltbefehl"
    });

    history = history.slice(0, 3);
    changed = true;

} else if (msg.alarm === false && activeRecord) {
    // Alarm condition ended: update the existing record.
    activeRecord.clearedAt = timestamp;
    activeRecord.status = "GEGANGEN";
    changed = true;
}

// Write only when an alarm appears or clears.
if (changed) {
    context.set("fanAlarmHistory", history, "file");
}

msg.payload = history;
msg.topic = "Fan Alarm History";

return msg;

// Assumed power for learning, not a measured value.
const assumedPowerW = 2;
const hours = msg.fanCommandHours;

if (typeof hours !== "number" ||
    !Number.isFinite(hours) || hours < 0) {
    return null;
}

msg.fanPowerAssumedW = assumedPowerW;
msg.fanEnergyEstimateWh = hours * assumedPowerW;
msg.payload = msg.fanEnergyEstimateWh.toFixed(3) + " Wh";
return msg;
